/// Convert a `float` to the bit pattern of its half-precision representation.
///
/// Direct translation of:
///
/// ```c
/// uint16_t float2half(float flt) {
///     union { float flt; uint32_t num; } in;
///     uint32_t n, j;
///     in.flt = flt;
///     n = in.num;
///     j = (n >> 23) & 0x1ff;
///     return (uint16_t)((uint32_t)m__base[j] + ((n & 0x007fffff) >> m__shift[j]));
/// }
/// ```
///
/// # Safety
///
/// This function takes no pointers and performs no unsafe operations; it is
/// `unsafe` only because it is exported with the C ABI.
#[unsafe(no_mangle)]
pub extern "C" fn float2half(flt: f32) -> u16 {
    // Equivalent to the C union type-pun: reinterpret the float's bits.
    let n: u32 = f32::to_bits(flt);

    // Index is masked to 9 bits, so it is always within 0..512.
    let j: u32 = (n >> 23) & 0x1ff;
    let j = j as usize;

    let base = M_BASE[j] as u32;
    let shift = M_SHIFT[j] as u32;

    // Every table entry is < 32, so the shift never exceeds u32's width.
    let mantissa = (n & 0x007f_ffff) >> shift;

    // C computes the sum in `uint32_t` and then truncates to `uint16_t`.
    base.wrapping_add(mantissa) as u16
}
